```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "network_delay",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.span_name, count(*) n, approx_quantile(c.duration,0.5)/1e6 client_p50_ms, approx_quantile(c.duration,0.95)/1e6 client_p95_ms, approx_quantile(sv.duration,0.5)/1e6 geo_server_p50_ms, approx_quantile(sv.duration,0.95)/1e6 geo_server_p95_ms FROM abnormal_traces c JOIN abnormal_traces sv ON sv.trace_id=c.trace_id AND sv.parent_span_id=c.span_id WHERE c.service_name='search' AND c.span_name='geo.Geo/Nearby' AND sv.service_name='geo' GROUP BY 1",
          "claim": "search's client calls to geo.Geo/Nearby take about 1.6–2.6 s, while geo's own server spans stay at about 0.2 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM normal_traces WHERE span_name IN ('geo.Geo/Nearby','search.Search/Nearby') GROUP BY 1,2,3 UNION ALL SELECT service_name, span_name, attr_span_kind, count(*), approx_quantile(duration,0.95)/1e6 FROM abnormal_traces WHERE span_name IN ('geo.Geo/Nearby','search.Search/Nearby') GROUP BY 1,2,3",
          "claim": "Before the incident search's geo client p95 was 0.6 ms; during it rose to about 2.5 s, while geo server p95 stayed about 0.2 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT date_trunc('minute', time) m, service_name, span_name, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95ms FROM abnormal_traces WHERE (service_name='search' AND span_name LIKE 'geo%') OR (service_name='geo') GROUP BY 1,2,3 ORDER BY 1,2,3",
          "claim": "Across every abnormal minute, search-to-geo client p95 tracks the 1.6–2.9 s range while geo server p95 remains about 0.2–0.3 ms."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE span_name IN ('search.Search/Nearby','HTTP /hotels') GROUP BY 1,2,3",
          "claim": "The frontend's /hotels server p95 (about 2.6 s) and its search.Search/Nearby client p95 (about 2.6 s) match search's own server p95 (about 2.6 s), so the delay passes straight through to users."
        }
      ]
    }
  ]
}
```

